Now the JS:

```js
(function () {
  const sections = Array.from(document.querySelectorAll('main section'));
  const links = Array.from(document.querySelectorAll('nav a'));
  const linkById = new Map(links.map(l => [l.hash.slice(1), l]));

  const spy = new IntersectionObserver(entries => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        links.forEach(l => l.classList.remove('active'));
        const link = linkById.get(entry.target.id);
        if (link) link.classList.add('active');
      }
    }
  }, { rootMargin: '-25% 0px -65% 0px' });
  sections.forEach(s => spy.observe(s));

  function currentSectionIndex() {
    const top = window.scrollY + window.innerHeight * 0.35;
    let idx = 0;
    for (let i = 0; i < sections.length; i++) {
      if (sections[i].offsetTop <= top) idx = i;
    }
    return idx;
  }

  document.addEventListener('keydown', (e) => {
    if (e.target.closest('input, textarea')) return;
    let d = 0;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === 'PageDown') d = 1;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp' || e.key === 'PageUp') d = -1;
    else return;
    e.preventDefault();
    const i = Math.min(sections.length - 1, Math.max(0, currentSectionIndex() + d));
    sections[i].scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
})();
```

Caveat: hijacking ArrowDown/Up might annoy scrollers; for a "presentation," it's OK. I might keep only ArrowRight/ArrowLeft and PageUp/PageDown. Let me use ArrowRight/ArrowLeft + PageDown/PageUp to avoid conflict with vertical scroll.

