1137:/**
1138: * Formats an exposure time in nanoseconds as a camera shutter speed string.
1139: *
1140: * - Sub-half-second exposures are shown as a reciprocal fraction (e.g. "1/30s", "1/1000s").
1141: * - Exposures of 0.5s or longer are shown as decimal seconds (e.g. "0.5s", "1s", "2.25s").
1142: * - Non-positive values return an empty string.
1143: */
1144:fun formatShutterSpeed(exposureTimeNs: Long): String {
1145:    if (exposureTimeNs <= 0L) return ""
1146:    return if (exposureTimeNs >= 500_000_000L) {
1147:        // 0.5s or longer: format as decimal seconds using integer math to avoid locale/float issues.
1148:        val totalCentiseconds = exposureTimeNs / 10_000_000L // 1 centisecond = 10ms
1149:        val wholeSeconds = totalCentiseconds / 100L
1150:        val fraction = totalCentiseconds % 100L
1151:        val fractionStr = when {
1152:            fraction == 0L -> ""
1153:            fraction < 10L -> "0$fraction"
1154:            fraction % 10L == 0L -> (fraction / 10L).toString()
1155:            else -> fraction.toString()
1156:        }
1157:        if (fractionStr.isEmpty()) "${wholeSeconds}s" else "${wholeSeconds}.${fractionStr}s"
1158:    } else {
1159:        // Under 0.5s: format as 1/N with the nearest integer denominator.
1160:        val denominator = (1_000_000_000.0 / exposureTimeNs).roundToInt().coerceAtLeast(1)
1161:        "1/${denominator}s"
1162:    }
1163:}
