import struct, os, zlib

def png_chunks(path):
    out = []
    with open(path,'rb') as f:
        sig = f.read(8)
        assert sig == b'\x89PNG\r\n\x1a\n'
        while True:
            hdr = f.read(8)
            if len(hdr) < 8: break
            length, ctype = struct.unpack('>I4s', hdr)
            data = f.read(length)
            f.read(4)  # crc
            if ctype in (b'tEXt', b'iTXt', b'zTXt', b'eXIf', b'iCCP', b'sRGB', b'gAMA', b'cHRM', b'pHYs'):
                if ctype == b'zTXt':
                    try: data = zlib.decompress(data[1+data.index(b'\0')+1])
                    except Exception: pass
                out.append((ctype.decode(), data[:120]))
    return out

for f in sorted(os.listdir('textures')):
    ch = png_chunks(f'textures/{f}')
    if ch:
        print(f, ch)
print("done scanning")
EOF"}

